local captureMetatable = {
 __index = function(object, key) local cell = rawget(object, false)[key]; return cell[1][cell[2]] end,
 __newindex = function(object, key, value) local cell = rawget(object, false)[key]; cell[1][cell[2]] = value end
}
local function closeCapturedValues(groups, values, first)
 local closed, index = {}, 1
 while index <= #groups do
  local cells, keep = groups[index], false
  for key = 0, #cells do
   local cell = cells[key]
   if cell[1] == values then
    if cell[2] >= first then closed[cell[2]] = values[cell[2]]; cell[1] = closed else keep = true end
   end
  end
  if keep then index = index + 1 else groups[index] = groups[#groups]; groups[#groups] = nil end
 end
end
