functions["runBuffCardUpdates"] = function(upvalues, ...)
  while true do
    environment.task.wait(0.05)
    for buffId in environment.pairs(upvalues[0].ActiveBuffs) do
      if not upvalues[1].Cards[buffId] then
        upvalues[2](buffId)
      end
    end
    for buffId, card in environment.pairs(upvalues[1].Cards) do
      if not upvalues[0].ActiveBuffs[buffId] then
        upvalues[3](buffId)
      else
        local buff = upvalues[0].ActiveBuffs[buffId]
        if buff and card.BarFill then
          local remaining = environment.math.max(0, buff.endTime - environment.tick())
          local duration = buff.duration or 3
          local progress = environment.math.clamp(remaining / duration, 0, 1)
          card.BarFill.Size = environment.UDim2.new(progress, 0, 1, 0)
          card.BarFill.BackgroundColor3 = environment._G.GLUTO_THEME_DIM:Lerp(environment._G.GLUTO_THEME, progress)
          if card.TimeLbl then
            card.TimeLbl.Text = environment.string.format("%.1fs", remaining)
          end
        end
      end
    end
  end
end

