functions["chooseRandomGeneratorPoint"] = function(upvalues, ...)
  local generators = upvalues[0].GB_GetAllGenerators()
  if not generators or #generators == 0 then
    return nil
  end
  local availablePoints = {}
  for _, generator in environment.ipairs(generators) do
    if generator and generator.Parent then
      for _, point in environment.ipairs(upvalues[0].GB_GetPoints(generator)) do
        if point and point.Parent then
          environment.table.insert(availablePoints, point)
        end
      end
    end
  end
  if #availablePoints == 0 then
    return nil
  end
  return availablePoints[environment.math.random(1, #availablePoints)]
end

