functions["findNearestCachedGeneratorPoint"] = function(upvalues, ...)
  local character = upvalues[0].Character
  local rootPart = character and character:FindFirstChild("HumanoidRootPart")
  if not rootPart then
    return nil
  end
  local closestPoint
  local closestDistance = environment.math.huge
  for _, generator in environment.pairs(upvalues[1].GB_GetAllGeneratorsCached()) do
    for _, point in environment.pairs(upvalues[1].GB_GetPoints(generator)) do
      local distance = (rootPart.Position - point.Position).Magnitude
      if distance < closestDistance then
        closestDistance = distance
        closestPoint = point
      end
    end
  end
  return closestPoint, closestDistance
end

