functions["findNearbyGeneratorPoint"] = function(upvalues, ...)
  local character = upvalues[0].Character
  local rootPart = character and character:FindFirstChild("HumanoidRootPart")
  if not rootPart then
    return nil
  end
  local closestPoint
  local closestDistance = 5.5
  for _, generator in environment.ipairs(upvalues[1].GB_GetAllGenerators()) do
    for _, point in environment.ipairs(upvalues[1].GB_GetPoints(generator)) do
      if point and point.Parent then
        local distance = (rootPart.Position - point.Position).Magnitude
        if distance < closestDistance then
          closestDistance = distance
          closestPoint = point
        end
      end
    end
  end
  return closestPoint
end

